"""Patch 48: the previous overview tiles restored, each with its scenario and a line of facts.
Frontend only. Requires patch 47. Run from the repository root. Checked against the exact
files it was written for; nothing is written unless all of it matches. Safe to re-run."""
import hashlib, os, sys
def abort(msg):
    sys.exit(f"ABORT: {msg}. No files were written.")
