CL_OLD = 'thumbnails and the benchmark figures to their source files. 359 tests pass.\n'
CL_NEW = 'thumbnails and the benchmark figures to their source files. 359 tests pass.\n\n**The overview tiles, as they were, with what each case is.** The previous tiles are restored,\neach now leading with its scenario - what the case tests - and a line of facts: the image time,\nvessels tracked and candidates replayed. The overview and benchmark endpoints stay available.\n'
read = lambda p: open(p, encoding="utf-8").read()
sha = lambda p: hashlib.sha256(open(p, "rb").read()).hexdigest()
writes, skipped = {}, 0
for p, v in REPLACE.items():
    if not os.path.exists(p): abort(f"{p} is missing")
    if read(p) == v["after"]: skipped += 1
    elif sha(p) == v["before"]: writes[p] = v["after"]
    else: abort(f"{p} is not the version this patch was written for; send its sha256")
cl = read("CHANGELOG.md")
if CL_NEW in cl: skipped += 1
elif cl.count(CL_OLD) == 1: writes["CHANGELOG.md"] = cl.replace(CL_OLD, CL_NEW, 1)
else: abort("CHANGELOG.md: the patch 47 entry this appends after was not found - apply patch 47 first")
for p, text in writes.items():
    open(p, "w", encoding="utf-8").write(text)
print(f"patch 48: {len(writes)} files written, {skipped} already in place.")
